type DailyContentCache={ayah:DailyAyah;hadith:DailyHadith;name:DivineName;dua:any};
function useHomeData() {
  const {location}=useAppLocation(); const {settings}=useWorshipSettings(); const dateKey=new Date().toISOString().slice(0,10);
  const [snapshot,setSnapshot]=useState<PrayerSnapshot|null>(null); const[ayah,setAyah]=useState<DailyAyah|null>(null); const[hadith,setHadith]=useState<DailyHadith|null>(null); const[name,setName]=useState<DivineName|null>(null); const[dua,setDua]=useState<any>(null); const[cached,setCached]=useState(false); const[error,setError]=useState('');
  const applyDaily=(daily:DailyContentCache)=>{setAyah(daily.ayah);setHadith(daily.hadith);setName(daily.name);setDua(daily.dua)};
  const load=async()=>{if(!location)return;setError('');try{const[p,a,h,n,duas]=await Promise.all([managedPrayerSnapshot(location,settings),getAyahOfDay(),getDailyHadith(),getNameOfDay(),getDuas('morning')]);const daily={ayah:a,hadith:h,name:n,dua:duas[0]};setSnapshot(p.snapshot);setCached(p.cached);applyDaily(daily);await saveDailyContent(dateKey,daily);}catch(e:any){const saved=await loadDailyContent<DailyContentCache>(dateKey);if(saved){applyDaily(saved);setCached(true)}else setError(e.message||'Please check your connection.')}};
  useEffect(()=>{loadDailyContent<DailyContentCache>(dateKey).then(saved=>saved&&applyDaily(saved));setSnapshot(null);if(location)load()},[location?.latitude,location?.longitude,settings.calculationMethod,settings.madhab,settings.timeFormat]);
  return{snapshot,ayah,hadith,name,dua,location,cached,error,load};
}
function getNext(prayers: Prayer[]) {
  const d = new Date(); const now = d.getHours() * 60 + d.getMinutes();
  return prayers.find(p => { const [h,m] = p.raw.split(':').map(Number); return h*60+m > now; }) || prayers[0];
}
function untilPrayer(prayer?: Prayer) {
  if (!prayer) return '';
  const [h,m] = prayer.raw.split(':').map(Number); const now = new Date(); const target = new Date(); target.setHours(h,m,0,0); if (target < now) target.setDate(target.getDate()+1);
  const mins = Math.max(0, Math.floor((target.getTime()-now.getTime())/60000)); return `${Math.floor(mins/60)}h ${mins%60}m`;
}

function HomeScreen() {
  const hour=new Date().getHours();const greeting=hour<12?'A purposeful morning':hour<18?'A purposeful afternoon':'A peaceful evening'; const nav = useNavigation<any>(); const locationState=useAppLocation(); const { width } = useWindowDimensions(); const wide = width >= 760; const data = useHomeData(); const next = data.snapshot ? getNext(data.snapshot.prayers) : undefined; const dateKey=new Date().toISOString().slice(0,10); const[completed,setCompleted]=useState<string[]>([]);const[history,setHistory]=useState<Record<string,string[]>>({});const[quickCount,setQuickCount]=useState(0);const[quranPosition,setQuranPosition]=useState<any>(null);const[refreshing,setRefreshing]=useState(false);
  const hydrateLocal=()=>Promise.all([loadPrayerCompletion(dateKey).then(setCompleted),loadPrayerHistory().then(setHistory),loadQuickTasbih().then(setQuickCount),loadReadingPosition().then(setQuranPosition)]);useEffect(()=>{hydrateLocal()},[dateKey]);const togglePrayer=(name:string)=>setCompleted(current=>{const next=current.includes(name)?current.filter(x=>x!==name):[...current,name];savePrayerCompletion(dateKey,next).then(()=>loadPrayerHistory().then(setHistory));return next});const addQuick=()=>setQuickCount(value=>{const next=value+1;saveQuickTasbih(next);if(Platform.OS!=='web')Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);return next});const onRefresh=async()=>{setRefreshing(true);await Promise.all([data.load(),hydrateLocal()]);setRefreshing(false)};const weekTotal=Object.entries(history).filter(([key])=>Date.now()-new Date(key).getTime()<7*86400000).reduce((sum,[,items])=>sum+items.length,0);let streak=0;for(let i=0;i<60;i++){const d=new Date();d.setDate(d.getDate()-i);const key=d.toISOString().slice(0,10);if((history[key]||[]).length>=5)streak++;else if(i>0||completed.length<5)break}
  const tools = [
    ['book-outline','Quran',()=>nav.navigate('Quran')], ['compass-outline','Qibla',()=>nav.navigate('Prayer',{screen:'Qibla'})],
    ['sunny-outline','Morning Adhkar',()=>nav.navigate('Library',{screen:'Adhkar',params:{initial:'morning'}})], ['moon-outline','Evening Adhkar',()=>nav.navigate('Library',{screen:'Adhkar',params:{initial:'evening'}})],
    ['radio-outline','Tasbih',()=>nav.navigate('Library',{screen:'Tasbih'})], ['headset-outline','Audio',()=>nav.navigate('Quran')],
    ['location-outline','Location',()=>nav.navigate('Prayer',{screen:'Location Setup'})], ['notifications-outline','Notifications',()=>nav.navigate('Prayer',{screen:'Notifications'})],
    ['calendar-outline','Hijri',()=>nav.navigate('Prayer',{screen:'Hijri Calendar'})], ['moon-outline','Ramadan',()=>nav.navigate('Prayer',{screen:'Ramadan'})],
  ];
  return <Page><ScrollView contentContainerStyle={s.scroll} showsVerticalScrollIndicator={false} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={C.green}/>}>
    <View style={s.greeting}><View><Text style={s.salam}>السَّلَامُ عَلَيْكُمْ</Text><Text style={s.greetingTitle}>{greeting}</Text></View><View style={s.avatar}>{ico('moon',19,C.white)}</View></View>
    {!data.location?<LocationPrompt/>:data.error && !data.snapshot ? <ErrorState message={data.error} retry={data.load} /> : <>
      <View style={s.hero}><Image source={require('./assets/hero-mosque-scene.png')} resizeMode="cover" style={s.heroBg}/>
        <LinearGradient colors={['rgba(30,30,63,.92)','rgba(56,48,103,.54)','rgba(11,120,145,.08)']} start={{x:0,y:.5}} end={{x:1,y:.5}} style={StyleSheet.absoluteFill} />
        <Pressable onPress={locationState.clear} style={s.locationPill}>{ico('location',13,'#FFE5A5')}<Text numberOfLines={1} style={s.locationText}>{data.location?.label}</Text></Pressable>
        <Text style={s.hijri}>{data.snapshot?.hijri || 'Loading Hijri date…'} · {new Date().toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}{data.cached?' · CACHED':''}</Text>
        <Text style={s.nextLabel}>NEXT · {next?.name?.toUpperCase() || '—'}</Text><Text style={s.heroTime}>{next?.time || '—'}</Text>
        <View style={s.heroFooter}><View style={s.countPill}>{ico('time-outline',14,C.white)}<Text style={s.countText}>in {untilPrayer(next)}</Text></View><Pressable onPress={()=>nav.navigate('Prayer')} style={s.heroCta}><Text style={s.heroCtaText}>Prayer schedule</Text>{ico('arrow-forward',15,C.white)}</Pressable></View>
      </View>
      <View style={s.prayerRail}>{data.snapshot?.prayers.filter(p=>p.name!=='Sunrise').map((p,i)=>{const checked=completed.includes(p.name);return <Pressable accessibilityRole="checkbox" accessibilityState={{checked}} onPress={()=>togglePrayer(p.name)} key={p.name} style={[s.railItem,p.name===next?.name&&s.railItemActive]}><View style={[s.railIcon,checked&&{backgroundColor:C.green}]}>{ico(checked?'checkmark':['moon-outline','sunny-outline','partly-sunny-outline','cloudy-night-outline','moon-outline'][i] as any,17,checked?C.white:C.green)}</View><Text style={s.railName}>{p.name}</Text><Text style={s.railTime}>{p.time.replace(' ','\n')}</Text></Pressable>})}</View><View style={s.homeProgress}><View><Text style={s.sourceTitle}>{completed.length}/5 prayers today</Text><Text style={s.sourceBody}>{streak} day streak · {weekTotal}/35 this week</Text></View><View style={s.homeProgressRing}><Text style={s.progressCount}>{completed.length*20}%</Text></View></View>
    </>}
    <Section title="Daily essentials" action="Open library" onPress={()=>nav.navigate('Library')} />
    <View style={s.toolGrid}>{tools.map(([iconName,label,onPress]:any,index:number)=><MotionPress key={label} onPress={onPress} style={[s.tool,wide&&s.toolWide]}><View style={s.toolInner}><ToolGraphic tool={label}/><Text style={s.toolLabel}>{label}</Text></View></MotionPress>)}</View>
    <Section title="Daily reflection" action="Refresh" onPress={onRefresh}/>
    <View style={s.dailyGrid}><View style={s.dailyCard}><Text style={s.dailyKicker}>AYAH OF THE DAY</Text><Text numberOfLines={3} style={s.dailyArabic}>{data.ayah?.arabic||'Loading verified Quran text…'}</Text><Text numberOfLines={4} style={s.dailyBody}>{data.ayah?.translation}</Text><Text style={s.dataMeta}>{data.ayah?.reference}</Text></View><View style={s.dailyCard}><Text style={s.dailyKicker}>NAME OF ALLAH</Text><Text style={s.nameOfDay}>{data.name?.name}</Text><Text style={s.dailyTitle}>{data.name?.transliteration}</Text><Text style={s.dailyBody}>{data.name?.meaning}</Text></View><View style={s.dailyCard}><Text style={s.dailyKicker}>DUA OF THE DAY</Text><Text numberOfLines={3} style={s.dailyArabic}>{data.dua?.arabic||'Loading verified dua…'}</Text><Text numberOfLines={4} style={s.dailyBody}>{data.dua?.translation}</Text></View><Pressable onPress={addQuick} style={[s.dailyCard,s.quickTasbih]}><ToolGraphic tool="Tasbih" size={52}/><Text style={s.dailyKicker}>QUICK TASBIH</Text><Text style={s.quickCount}>{quickCount}</Text><Text style={s.dailyBody}>Tap to count · saved locally</Text></Pressable></View>
    <Pressable onPress={()=>nav.navigate('Prayer',{screen:'Weekly Summary'})} style={s.weekSummary}><View><Text style={s.weekSummaryTitle}>This week</Text><Text style={s.weekSummaryBody}>{weekTotal} of 35 prayers marked · {streak} day streak</Text></View>{ico('arrow-forward',18,C.white)}</Pressable>
    <Section title="Continue reading" action="Open Quran" onPress={()=>nav.navigate('Quran')} />
    <View style={s.readCard}><Image source={require('./assets/quran-scene.png')} resizeMode="cover" style={s.heroBg}/>
      <LinearGradient colors={['rgba(39,34,82,.95)','rgba(76,58,130,.55)','rgba(11,120,145,.08)']} start={{x:0,y:.5}} end={{x:1,y:.5}} style={StyleSheet.absoluteFill} />
      <Text style={s.readKicker}>{quranPosition?'CONTINUE READING':'FEATURED READING'}</Text><Text style={s.readArabic}>{quranPosition?'۝':'يس'}</Text><Text style={s.readTitle}>{quranPosition?quranPosition.surahName:'Surah Ya-Sin'}</Text><Text style={s.readMeta}>{quranPosition?`${quranPosition.verseKey} · Page ${quranPosition.page||'—'}`:'83 verses · Makkan'}</Text><Pressable onPress={()=>nav.navigate('Quran',{screen:'Reader',params:{chapter:quranPosition?{id:quranPosition.surahId,name_simple:quranPosition.surahName,name_arabic:'',verses_count:0}:{id:36,name_simple:'Ya-Sin',name_arabic:'يس',verses_count:83},focusVerse:quranPosition?.verseKey}})} style={s.whiteButton}><Text style={s.whiteButtonText}>{quranPosition?'Continue':'Read now'}</Text>{ico('arrow-forward',14,C.green)}</Pressable>
    </View>
    <Section title="Hadith of the day" />
    <View style={s.hadithCard}><Text style={s.quote}>“</Text><LiveBadge source="ISLAMIC.APP" /><Text numberOfLines={6} style={s.hadithText}>{data.hadith?.text || 'Loading today’s authenticated hadith…'}</Text><View style={s.hadithFoot}><Text style={s.meta}>{data.hadith ? `${data.hadith.collection.toUpperCase()} · ${data.hadith.number}` : ''}</Text>{ico('bookmark-outline',20,C.green)}</View></View>
  </ScrollView></Page>;
}
const CARD_GREEN = { backgroundColor: '#EEEAFF' }; const CARD_GOLD = { backgroundColor: '#FFF1DD' };

function PrayerScreen({navigation}:any) {
  const {location}=useAppLocation(); const {settings}=useWorshipSettings(); const [snap,setSnap]=useState<PrayerSnapshot|null>(null); const [cached,setCached]=useState(false); const [error,setError]=useState(''); const [completed,setCompleted]=useState<string[]>([]);
  const dateKey=new Date().toISOString().slice(0,10); useEffect(()=>{loadPrayerCompletion(dateKey).then(setCompleted)},[dateKey]);
  const togglePrayer=(name:string)=>{if(name==='Sunrise')return;setCompleted(current=>{const next=current.includes(name)?current.filter(x=>x!==name):[...current,name];savePrayerCompletion(dateKey,next).catch(()=>{});return next})};
  const load=async()=>{if(!location)return;setError('');try{const value=await managedPrayerSnapshot(location,settings);setSnap(value.snapshot);setCached(value.cached);if(settings.remindersEnabled)schedulePrayerNotifications(value.snapshot,settings).catch(()=>{})}catch(e:any){setError(e.message)}}; useEffect(()=>{setSnap(null);load()},[location?.latitude,location?.longitude,settings.calculationMethod,settings.madhab,settings.timeFormat]);
  const next=snap?getNext(snap.prayers):undefined; const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i);return d;}); const done=completed.length;
  return <Page><ScrollView contentContainerStyle={s.scroll} showsVerticalScrollIndicator={false}><TopBar overline={cached?'OFFLINE CACHE':'LIVE PRAYER DATA'} title="Prayer times" right={<ToolGraphic tool="Qibla" size={46}/>} />
    <View style={s.dayStrip}>{days.map((d,i)=><View key={i} style={[s.day,i===0&&s.dayActive]}><Text style={[s.dayName,i===0&&s.dayText]}>{d.toLocaleDateString('en',{weekday:'short'})}</Text><Text style={[s.dayNum,i===0&&s.dayText]}>{d.getDate()}</Text></View>)}</View>
    {!location?<LocationPrompt compact/>:error?<ErrorState message={error} retry={load}/>:!snap?<Spinner/>:<><LinearGradient colors={['#2A2849','#5146A4']} style={s.nextCard}><View><LiveBadge source={cached?'SAVED ON DEVICE':'ALADHAN'}/><Text style={s.nextCardLabel}>NEXT PRAYER</Text><Text style={s.nextCardName}>{next?.name}</Text><Text style={s.nextCardTime}>{next?.time}</Text><View style={s.countPill}><Text style={s.countText}>Begins in {untilPrayer(next)}</Text></View></View><View style={s.moonOrb}>{ico('moon',42,'#FFE3A4')}</View></LinearGradient>
      <View style={s.prayerProgress}><View style={{flex:1}}><Text style={s.sourceTitle}>Today’s Salah</Text><Text style={s.sourceBody}>{done} of 5 prayers marked complete</Text></View><View style={s.progressTrack}><View style={[s.progressFill,{width:`${done*20}%`} as any]}/></View><Text style={s.progressCount}>{done}/5</Text></View>
      <Section title="Today’s schedule" action={`${settings.calculationMethodName} · ${settings.madhab==='hanafi'?'Hanafi':'Shafi'}`} onPress={()=>navigation.getParent()?.navigate('Settings')} />
      <View style={s.prayerList}>{snap.prayers.map((p,i)=>{const checked=completed.includes(p.name);return <Pressable accessibilityRole={p.name==='Sunrise'?undefined:'checkbox'} accessibilityState={p.name==='Sunrise'?undefined:{checked}} onPress={()=>togglePrayer(p.name)} key={p.name} style={[s.prayerRow,p.name===next?.name&&s.prayerRowLive]}><View style={[s.prayerSymbol,checked&&s.prayerSymbolDone]}>{ico(checked?'checkmark':'moon-outline',21,checked?C.white:C.green)}</View><View style={{flex:1}}><Text style={s.prayerName}>{p.name}</Text><Text style={s.meta}>{p.name==='Sunrise'?'Solar event':checked?'Completed':p.name===next?.name?'Up next':'Tap to mark complete'}</Text></View><Text style={s.prayerValue}>{p.time}</Text>{p.name!=='Sunrise'&&ico(checked?'checkmark-circle':'ellipse-outline',18,checked?C.green:C.muted)}</Pressable>})}</View>
      <View style={s.sourceCard}>{ico('shield-checkmark-outline',21,C.green)}<View style={{flex:1}}><Text style={s.sourceTitle}>{cached?'Saved prayer schedule':'Live calculation'}</Text><Text style={s.sourceBody}>{snap.method} · {snap.timezone} · {settings.timeFormat}-hour</Text></View></View><Section title="Prayer tools"/><View style={s.prayerTools}>{[['compass-outline','Qibla','Qibla'],['location-outline','Location','Location Setup'],['notifications-outline','Notifications','Notifications'],['volume-high-outline','Adhan','Adhan'],['calendar-outline','Hijri calendar','Hijri Calendar'],['moon-outline','Ramadan','Ramadan'],['business-outline','Mosques','Mosques'],['book-outline','Worship guides','Worship Guides'],['stats-chart-outline','Weekly Summary','Weekly Summary']].map(([icon,label,screen]:any,i)=><MotionPress key={label} onPress={()=>navigation.navigate(screen)} style={s.prayerTool}><View style={s.prayerToolInner}><ToolGraphic tool={label} size={54}/><Text style={s.prayerToolText}>{label}</Text></View></MotionPress>)}</View></>}
  </ScrollView></Page>;
}

function QuranHome({navigation}:any){
 const[chapters,setChapters]=useState<Chapter[]>([]);const[query,setQuery]=useState('');const[debounced,setDebounced]=useState('');const[error,setError]=useState('');const[position,setPosition]=useState<any>(null);const[bookmarkCount,setBookmarkCount]=useState(0);const[noteCount,setNoteCount]=useState(0);const[recent,setRecent]=useState<number[]>([]);const{preferences}=useQuranPreferences();
 const load=()=>getChapters().then(setChapters).catch(e=>setError(e.message));const hydrate=()=>Promise.all([loadReadingPosition().then(setPosition),loadBookmarks().then(x=>setBookmarkCount(x.length)),loadNotes().then(x=>setNoteCount(x.length)),loadRecentSurahs().then(setRecent)]);useEffect(()=>{load();hydrate()},[]);useEffect(()=>{const id=setTimeout(()=>setDebounced(query.trim()),250);return()=>clearTimeout(id)},[query]);
 const shown=chapters.filter(c=>`${c.id} ${c.name_simple} ${c.name_arabic} ${c.translated_name?.name}`.toLowerCase().includes(debounced.toLowerCase()));const open=(chapter:Chapter,mode='both',focusVerse?:string)=>navigation.navigate('Reader',{chapter,mode,focusVerse});const featured={id:55,name_simple:'Ar-Rahman',name_arabic:'الرحمن',translated_name:{name:'The Most Merciful'},verses_count:78};const submit=()=>{const ref=query.match(/^(\d{1,3}):(\d{1,3})$/);if(ref){const chapter=chapters.find(c=>c.id===Number(ref[1]));if(chapter)return open(chapter,'both',query)}navigation.navigate('Quran Search',{initialQuery:query})};
 const shortcuts:any[]=[['Quran Search','Quran Search',undefined],['Translations','Translations',undefined],['30 Juz','Juz Directory',undefined],['Bookmarks','Bookmarks',`${bookmarkCount}`],['Notes','Notes',`${noteCount}`],['Reading Plans','Reading Plans',undefined],['Hifz','Hifz',undefined],['Offline Quran','Quran Preload',undefined]];
 return <Page><ScrollView contentContainerStyle={s.scroll} showsVerticalScrollIndicator={false}><TopBar overline="AL-QURAN CLOUD · LIVE" title="The Noble Quran" right={<ToolGraphic tool="Quran" size={48}/>}/><View style={s.search}>{ico('search-outline',19,C.muted)}<TextInput value={query} onChangeText={setQuery} onSubmitEditing={submit} returnKeyType="search" style={s.searchInput} placeholder="Search Surah, meaning, or 2:255" placeholderTextColor="#929B96"/>{query.length>0&&<Pressable onPress={()=>setQuery('')}>{ico('close-circle',18,C.muted)}</Pressable>}</View>{position&&<Pressable onPress={()=>{const chapter=chapters.find(c=>c.id===position.surahId);if(chapter)open(chapter,'both',position.verseKey)}} style={s.continueBar}><ToolGraphic tool="Quran Arabic" size={48}/><View style={{flex:1}}><Text style={s.dailyKicker}>CONTINUE READING</Text><Text style={s.settingName}>{position.surahName} · {position.verseKey}</Text><Text style={s.meta}>Page {position.page||'—'} · saved locally</Text></View>{ico('arrow-forward',18,C.green)}</Pressable>}<View style={s.quranHero}><Image source={require('./assets/quran-scene.png')} resizeMode="cover" style={s.heroBg}/><LinearGradient colors={['rgba(41,37,80,.96)','rgba(89,65,139,.52)','transparent']} start={{x:0,y:.5}} end={{x:1,y:.5}} style={StyleSheet.absoluteFill}/><LiveBadge source="AL QURAN CLOUD"/><Text style={s.quranArabic}>الرَّحْمَٰن</Text><Text style={s.quranHeroTitle}>Read. Listen. Reflect.</Text><Text style={s.quranHeroMeta}>{preferences.scriptName} · {preferences.translationName}</Text><Pressable style={s.whiteButton} onPress={()=>open(featured)}><Text style={s.whiteButtonText}>Start reading</Text>{ico('play',13,C.green)}</Pressable></View><Section title="Study and progress"/><View style={s.quranFeatureGrid}>{shortcuts.map(([label,screen,badge])=><MotionPress key={label} onPress={()=>navigation.navigate(screen)} style={s.quranFeatureWrap}><View style={s.quranFeatureCard}><ToolGraphic tool={label} size={50}/><Text style={s.quranFeatureText}>{label}</Text>{badge!==undefined&&<Text style={s.quranFeatureBadge}>{badge}</Text>}</View></MotionPress>)}</View>{recent.length>0&&<><Section title="Recent Surahs"/><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{gap:8}}>{recent.map(id=>{const c=chapters.find(x=>x.id===id);return c?<Pressable key={id} onPress={()=>open(c)} style={s.recentChip}><Text style={s.settingName}>{c.name_simple}</Text><Text style={s.surahAr}>{c.name_arabic}</Text></Pressable>:null})}</ScrollView></>}<Section title="All surahs" action={`${shown.length} chapters`}/>{error?<ErrorState message={error} retry={load}/>:!chapters.length?<Spinner/>:<View style={s.surahList}>{shown.map(c=><Pressable key={c.id} onPress={()=>open(c)} style={s.surahRow}><View style={s.surahNum}><Text style={s.surahNumText}>{c.id}</Text></View><View style={{flex:1}}><Text style={s.surahName}>{c.name_simple}</Text><Text style={s.meta}>{c.translated_name?.name} · {c.verses_count} verses · {c.revelation_place}</Text></View><Text style={s.surahAr}>{c.name_arabic}</Text></Pressable>)}</View>}</ScrollView></Page>
}

function ReaderScreen({route,navigation}:any){
 const chapter:Chapter=route.params.chapter;const initial=route.params?.mode||'both';const focusVerse=route.params?.focusVerse;const{preferences,update}=useQuranPreferences();const[showArabic,setShowArabic]=useState(initial!=='english');const[showEnglish,setShowEnglish]=useState(initial!=='arabic'&&preferences.showTranslation);const[verses,setVerses]=useState<Verse[]>([]);const[bookmarks,setBookmarks]=useState<QuranBookmark[]>([]);const[error,setError]=useState('');const[cached,setCached]=useState(false);const{rtl}=useLanguage();const cacheKey=`${chapter.id}:${preferences.scriptEdition}:${preferences.translationEdition}`;
 const load=async()=>{setError('');const local=await loadSurahCache(cacheKey) as Verse[]|null;if(local){setVerses(local);setCached(true)}try{const fresh=await getVerses(chapter.id,{script:preferences.scriptEdition,translation:preferences.translationEdition});setVerses(fresh);setCached(false);await saveSurahCache(cacheKey,fresh)}catch(e:any){if(!local)setError(e.message)}};useEffect(()=>{load();loadBookmarks().then(setBookmarks)},[chapter.id,preferences.scriptEdition,preferences.translationEdition]);const toggle=(kind:'ar'|'en')=>{if(kind==='ar'){if(showArabic&&!showEnglish)return;setShowArabic(!showArabic)}else{if(showEnglish&&!showArabic)return;setShowEnglish(!showEnglish)}};
 const bookmark=async(v:Verse)=>setBookmarks(await toggleBookmark({verseKey:v.verse_key,surahId:chapter.id,surahName:chapter.name_simple,arabic:v.text_uthmani,translation:v.translation,savedAt:Date.now()}));const mark=async(v:Verse)=>{await saveReadingPosition({surahId:chapter.id,surahName:chapter.name_simple,verseKey:v.verse_key,ayah:Number(v.verse_key.split(':')[1]),page:v.page,updatedAt:Date.now()});Alert.alert('Reading position saved',`${chapter.name_simple} ${v.verse_key}`)};const share=(v:Verse)=>Share.share({message:`${v.text_uthmani}\n\n${v.translation||''}\n\nQuran ${v.verse_key} · ${preferences.translationName}`});
 return <Page><View style={s.readerBar}><IconButton name={rtl?'arrow-forward':'arrow-back'} onPress={()=>navigation.goBack()}/><View style={{alignItems:'center'}}><Text style={s.readerName}>{chapter.name_simple}</Text><Text style={s.meta}>{cached?'Available offline · ':''}{chapter.verses_count} verses</Text></View><Pressable onPress={()=>navigation.navigate('Reader Settings')} style={s.iconBtn}>{ico('options-outline',20,C.ink)}</Pressable></View><ScrollView contentContainerStyle={s.readerScroll} showsVerticalScrollIndicator={false}><LinearGradient colors={['#2A2849','#5146A4']} style={s.surahHead}><LiveBadge source={cached?'DEVICE CACHE':'AL QURAN CLOUD'}/><Text style={s.surahHeadAr}>{chapter.name_arabic}</Text><Text style={s.surahHeadEn}>{chapter.translated_name?.name}</Text><Text style={s.bismillah}>بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</Text></LinearGradient><View style={s.readerModes}><Pressable accessibilityRole="checkbox" accessibilityState={{checked:showArabic}} onPress={()=>toggle('ar')} style={[s.readerMode,showArabic&&s.readerModeActive]}><ToolGraphic tool="Arabic Quran" size={42}/><Text style={s.readerModeText}>Arabic</Text></Pressable><Pressable accessibilityRole="checkbox" accessibilityState={{checked:showEnglish}} onPress={()=>toggle('en')} style={[s.readerMode,showEnglish&&s.readerModeActive]}><ToolGraphic tool="English meaning" size={42}/><Text style={s.readerModeText}>Translation</Text></Pressable></View>{error?<ErrorState message={error} retry={load}/>:!verses.length?<Spinner/>:verses.map(v=>{const saved=bookmarks.some(x=>x.verseKey===v.verse_key);return <View key={v.id} style={[s.ayah,preferences.readingMode==='continuous'&&s.ayahContinuous,focusVerse===v.verse_key&&s.ayahSelected]}><View style={s.ayahTop}><Text style={s.ayahNo}>{v.verse_key}</Text><View style={s.ayahActions}><Pressable accessibilityLabel={`Play verse ${v.verse_key}`} onPress={()=>v.audio&&Linking.openURL(v.audio)}>{ico('play-circle',24,C.green)}</Pressable><Pressable accessibilityLabel={`${saved?'Remove bookmark from':'Bookmark'} verse ${v.verse_key}`} onPress={()=>bookmark(v)}>{ico(saved?'bookmark':'bookmark-outline',20,C.green)}</Pressable><Pressable accessibilityLabel={`More actions for verse ${v.verse_key}`} onPress={()=>navigation.navigate('Ayah Actions',{verse:v,chapter})}>{ico('ellipsis-horizontal-circle-outline',21,C.green)}</Pressable></View></View>{showArabic&&<Text style={[s.ayahAr,{fontSize:preferences.fontSize,lineHeight:preferences.fontSize*preferences.lineHeight}]}>{v.text_uthmani}</Text>}{showEnglish&&<Text style={[s.ayahTranslation,!showArabic&&{borderTopWidth:0,marginTop:8,paddingTop:0}]}>{v.translation}</Text>}<View style={s.ayahFooter}><Text style={s.ayahMeta}>Juz {v.juz} · Page {v.page} · {preferences.translationName}</Text><Pressable onPress={()=>mark(v)}><Text style={s.sectionAction}>Mark position</Text></Pressable></View></View>})}</ScrollView></Page>
}
function TranslationScreen({navigation}:any){const{preferences,update}=useQuranPreferences();const[editions,setEditions]=useState<QuranEdition[]>([]);const[query,setQuery]=useState('');const[language,setLanguage]=useState('en');const[error,setError]=useState('');useEffect(()=>{getQuranEditions().then(setEditions).catch(e=>setError(e.message))},[]);const languages=[['en','English'],['ur','Urdu'],['fr','French'],['tr','Turkish'],['id','Indonesian'],['ru','Russian'],['zh','Chinese']];const shown=editions.filter(e=>e.language===language&&`${e.englishName} ${e.name}`.toLowerCase().includes(query.toLowerCase()));return <Page><ToolBar title="Translation" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Translations" size={76}/><Text style={s.dataTitle}>Choose a translation</Text><Text style={s.intro}>Translations explain meaning and do not replace the Arabic Quran. Edition attribution remains visible in the reader.</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{gap:7}}>{languages.map(([code,name])=><ChoicePill key={code} label={name} selected={language===code} onPress={()=>setLanguage(code)}/>)}</ScrollView><View style={[s.search,{marginTop:13}]}>{ico('search-outline',18,C.muted)}<TextInput value={query} onChangeText={setQuery} placeholder="Search translator or edition" style={s.searchInput}/></View>{error?<ErrorState message={error}/>:!editions.length?<Spinner/>:<View style={s.settings}>{shown.map(e=><Pressable key={e.identifier} onPress={async()=>{await update({translationEdition:e.identifier,translationName:e.englishName,translationLanguage:languages.find(x=>x[0]===e.language)?.[1]||e.language});navigation.goBack()}} style={s.translationRow}><View style={s.languageBadge}><Text style={s.languageBadgeText}>{e.language.toUpperCase()}</Text></View><View style={{flex:1}}><Text style={s.settingName}>{e.englishName}</Text><Text style={s.meta}>{e.name} · {e.identifier}</Text></View>{ico(preferences.translationEdition===e.identifier?'checkmark-circle':'ellipse-outline',20,preferences.translationEdition===e.identifier?C.green:C.muted)}</Pressable>)}</View>}</ScrollView></Page>}

function QuranSearchScreen({route,navigation}:any){const{preferences}=useQuranPreferences();const[query,setQuery]=useState(route.params?.initialQuery||'');const[results,setResults]=useState<QuranSearchResult[]>([]);const[history,setHistory]=useState<string[]>([]);const[error,setError]=useState('');const[loading,setLoading]=useState(false);useEffect(()=>{loadSearchHistory().then(setHistory);if(route.params?.initialQuery)run(route.params.initialQuery)},[]);const run=async(value=query)=>{const q=value.trim();if(q.length<2)return;setLoading(true);setError('');try{const edition=/[\u0600-\u06ff]/.test(q)?preferences.scriptEdition:preferences.translationEdition;setResults((await searchQuran(q,edition)).slice(0,100));setHistory(await addSearchHistory(q))}catch(e:any){setError(e.message)}finally{setLoading(false)}};const open=(r:QuranSearchResult)=>navigation.navigate('Reader',{chapter:{id:r.surahId,name_simple:r.surahName,name_arabic:'',verses_count:0},focusVerse:r.verseKey});return <Page><ToolBar title="Quran search" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage} keyboardShouldPersistTaps="handled"><ToolGraphic tool="Quran Search" size={72}/><Text style={s.dataTitle}>Search Arabic or translation</Text><View style={s.search}>{ico('search-outline',19,C.muted)}<TextInput autoFocus value={query} onChangeText={setQuery} onSubmitEditing={()=>run()} returnKeyType="search" style={s.searchInput} placeholder="Mercy, الصبر, or 2:255"/><Pressable onPress={()=>run()}>{ico('arrow-forward-circle',22,C.green)}</Pressable></View>{history.length>0&&<><View style={s.historyHead}><Text style={s.preferenceLabel}>RECENT SEARCHES</Text><Pressable onPress={async()=>{await clearSearchHistory();setHistory([])}}><Text style={s.sectionAction}>Clear</Text></Pressable></View><View style={s.historyWrap}>{history.map(item=><Pressable key={item} onPress={()=>{setQuery(item);run(item)}} onLongPress={async()=>setHistory(await removeSearchHistory(item))} style={s.historyChip}><Text style={s.meta}>{item}</Text></Pressable>)}</View></>}{error?<ErrorState message={error} retry={()=>run()}/>:loading?<Spinner/>:<View>{results.map(r=><Pressable key={`${r.verseKey}-${r.edition}`} onPress={()=>open(r)} style={s.searchResult}><Text style={s.dataMeta}>{r.surahName} · {r.verseKey}</Text><Text numberOfLines={4} style={/[\u0600-\u06ff]/.test(r.text)?s.dataArabic:s.dataBody}>{r.text}</Text><Text style={s.meta}>{r.edition}</Text></Pressable>)}</View>}</ScrollView></Page>}

function BookmarkScreen({navigation}:any){const[items,setItems]=useState<QuranBookmark[]>([]);useEffect(()=>{const unsub=navigation.addListener('focus',()=>loadBookmarks().then(setItems));loadBookmarks().then(setItems);return unsub},[navigation]);return <Page><ToolBar title="Bookmarks" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Bookmarks" size={72}/><Text style={s.dataTitle}>{items.length} saved verses</Text>{!items.length?<View style={s.empty}><Text style={s.errorTitle}>No bookmarks yet</Text><Text style={s.errorText}>Use the bookmark action beside any verse.</Text></View>:items.map(item=><Pressable key={item.verseKey} onPress={()=>navigation.navigate('Reader',{chapter:{id:item.surahId,name_simple:item.surahName,name_arabic:'',verses_count:0},focusVerse:item.verseKey})} style={s.dataCard}><Text style={s.dataMeta}>{item.surahName} · {item.verseKey}</Text><Text numberOfLines={3} style={s.dataArabic}>{item.arabic}</Text><Text numberOfLines={3} style={s.dataBody}>{item.translation}</Text></Pressable>)}</ScrollView></Page>}
function NotesScreen({navigation}:any){const[items,setItems]=useState<QuranNote[]>([]);useEffect(()=>{const unsub=navigation.addListener('focus',()=>loadNotes().then(setItems));loadNotes().then(setItems);return unsub},[navigation]);return <Page><ToolBar title="Quran notes" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Notes" size={72}/><Text style={s.dataTitle}>{items.length} private notes</Text><Text style={s.intro}>Notes remain on this device and are never added to diagnostics.</Text>{!items.length?<View style={s.empty}><Text style={s.errorTitle}>No notes yet</Text><Text style={s.errorText}>Open verse actions to add a reflection.</Text></View>:items.map(item=><Pressable key={item.verseKey} onPress={()=>navigation.navigate('Note Editor',{verse:item,chapter:{id:item.surahId,name_simple:item.surahName}})} style={s.dataCard}><Text style={s.dataMeta}>{item.surahName} · {item.verseKey}</Text><Text style={s.noteText}>{item.note}</Text><Text style={s.meta}>{new Date(item.updatedAt).toLocaleDateString()}</Text></Pressable>)}</ScrollView></Page>}
function NoteEditor({route,navigation}:any){const verse:Verse=route.params.verse;const chapter:Chapter=route.params.chapter;const[text,setText]=useState(route.params.verse.note||'');const save=async()=>{if(!text.trim())return;await saveNote({verseKey:verse.verse_key,surahId:chapter.id,surahName:chapter.name_simple,arabic:verse.text_uthmani,translation:verse.translation,note:text.trim(),savedAt:route.params.verse.savedAt||Date.now(),updatedAt:Date.now()});navigation.goBack()};return <Page><ToolBar title={`Note · ${verse.verse_key}`} navigation={navigation}/><View style={s.dataPage}><Text style={s.dataArabic}>{verse.text_uthmani}</Text><TextInput multiline autoFocus value={text} onChangeText={setText} placeholder="Write a private reflection…" style={s.noteInput}/><View style={s.actionRow}><Pressable onPress={save} style={s.primary}><Text style={s.primaryText}>Save note</Text></Pressable>{route.params.verse.note&&<Pressable onPress={async()=>{await deleteNote(verse.verse_key);navigation.goBack()}} style={s.dangerButton}><Text style={s.dangerText}>Delete</Text></Pressable>}</View></View></Page>}

function ReaderSettingsScreen({navigation}:any){const{preferences,update}=useQuranPreferences();const scripts=[['quran-uthmani','Uthmani'],['quran-simple','Imla’i Simple'],['quran-uthmani-quran-academy','Quran Academy']];return <Page><ToolBar title="Reading settings" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Reader Settings" size={72}/><Section title="Arabic script"/><View style={s.choiceGrid}>{scripts.map(([id,name])=><ChoicePill key={id} label={name} selected={preferences.scriptEdition===id} onPress={()=>update({scriptEdition:id,scriptName:name})}/>)}</View><Section title="Reading mode"/><View style={s.choiceRow}><ChoicePill label="Ayah cards" selected={preferences.readingMode==='cards'} onPress={()=>update({readingMode:'cards'})}/><ChoicePill label="Continuous" selected={preferences.readingMode==='continuous'} onPress={()=>update({readingMode:'continuous'})}/></View><Section title="Arabic size" action={`${preferences.fontSize}px`}/><View style={s.stepper}><Pressable onPress={()=>update({fontSize:Math.max(18,preferences.fontSize-2)})} style={s.stepButton}>{ico('remove',20,C.green)}</Pressable><Text style={[s.previewArabic,{fontSize:preferences.fontSize}]}>ٱلْقُرْآنُ</Text><Pressable onPress={()=>update({fontSize:Math.min(40,preferences.fontSize+2)})} style={s.stepButton}>{ico('add',20,C.green)}</Pressable></View><Section title="Line spacing" action={preferences.lineHeight.toFixed(1)}/><View style={s.stepper}><Pressable onPress={()=>update({lineHeight:Math.max(1.4,+(preferences.lineHeight-.1).toFixed(1))})} style={s.stepButton}>{ico('remove',20,C.green)}</Pressable><Text style={s.settingName}>{preferences.lineHeight.toFixed(1)}×</Text><Pressable onPress={()=>update({lineHeight:Math.min(3,+(preferences.lineHeight+.1).toFixed(1))})} style={s.stepButton}>{ico('add',20,C.green)}</Pressable></View><Pressable onPress={()=>navigation.navigate('Translations')} style={s.referenceRow}><View><Text style={s.settingName}>Translation</Text><Text style={s.meta}>{preferences.translationName}</Text></View>{ico('arrow-forward',18,C.green)}</Pressable></ScrollView></Page>}

function AyahActionsScreen({route,navigation}:any){const verse:Verse=route.params.verse;const chapter:Chapter=route.params.chapter;const{preferences}=useQuranPreferences();const actions=[['copy-outline','Copy Arabic',()=>Clipboard.setStringAsync(verse.text_uthmani)],['copy-outline','Copy translation',()=>Clipboard.setStringAsync(verse.translation||'')],['share-outline','Share verse',()=>Share.share({message:`${verse.text_uthmani}\n\n${verse.translation||''}\n\nQuran ${verse.verse_key}`})],['create-outline','Add or edit note',()=>navigation.navigate('Note Editor',{verse,chapter})],['library-outline','Tafsir & compare',()=>navigation.navigate('Tafsir Compare',{verse,chapter})],['bookmark-outline','Save reading position',()=>saveReadingPosition({surahId:chapter.id,surahName:chapter.name_simple,verseKey:verse.verse_key,ayah:Number(verse.verse_key.split(':')[1]),page:verse.page,updatedAt:Date.now()})]];return <Page><ToolBar title={`Verse ${verse.verse_key}`} navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><Text style={s.dataArabic}>{verse.text_uthmani}</Text><Text style={s.dataBody}>{verse.translation}</Text><Text style={s.dataMeta}>{preferences.translationName}</Text><Section title="Actions"/><View style={s.settings}>{actions.map(([icon,label,action]:any)=><Pressable key={label} onPress={async()=>{await action();if(label.startsWith('Copy'))Alert.alert('Copied',label)}} style={s.setting}><MotionGlyph name={icon} size={19}/><Text style={[s.settingName,{flex:1}]}>{label}</Text>{ico('arrow-forward',17,C.muted)}</Pressable>)}</View></ScrollView></Page>}
function TafsirCompareScreen({route,navigation}:any){const verse:Verse=route.params.verse;const{preferences}=useQuranPreferences();const[rows,setRows]=useState<any[]>([]);const[error,setError]=useState('');const load=()=>getAyahEditions(verse.verse_key,[preferences.scriptEdition,preferences.translationEdition,'ar.jalalayn']).then(setRows).catch(e=>setError(e.message));useEffect(()=>{load()},[verse.verse_key,preferences.translationEdition]);return <Page><ToolBar title="Tafsir & comparison" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Tafsir" size={72}/><Text style={s.dataTitle}>Quran {verse.verse_key}</Text>{error?<ErrorState message={error} retry={load}/>:!rows.length?<Spinner/>:rows.map(row=><View key={row.edition} style={s.compareCard}><Text style={s.dataMeta}>{row.name} · {row.language.toUpperCase()}</Text><Text style={row.language==='ar'?s.dataArabic:s.dataBody}>{row.text}</Text></View>)}</ScrollView></Page>}

function JuzDirectoryScreen({navigation}:any){return <Page><ToolBar title="30 Juz" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="30 Juz" size={72}/><Text style={s.dataTitle}>Read by Juz</Text><View style={s.juzGrid}>{Array.from({length:30},(_,i)=>i+1).map(juz=><Pressable key={juz} onPress={()=>navigation.navigate('Juz Reader',{juz})} style={s.juzCard}><Text style={s.juzNo}>{juz}</Text><Text style={s.meta}>JUZ</Text></Pressable>)}</View></ScrollView></Page>}
function JuzReaderScreen({route,navigation}:any){const juz=route.params.juz;const{preferences}=useQuranPreferences();const[verses,setVerses]=useState<Verse[]>([]);const[error,setError]=useState('');const load=()=>getJuzVerses(juz,{script:preferences.scriptEdition,translation:preferences.translationEdition}).then(setVerses).catch(e=>setError(e.message));useEffect(()=>{load()},[juz,preferences.scriptEdition,preferences.translationEdition]);return <Page><ToolBar title={`Juz ${juz}`} navigation={navigation}/><ScrollView contentContainerStyle={s.readerScroll}>{error?<ErrorState message={error} retry={load}/>:!verses.length?<Spinner/>:verses.map(v=><View key={v.id} style={s.ayah}><Text style={s.dataMeta}>{v.surah_name} · {v.verse_key}</Text><Text style={[s.ayahAr,{fontSize:preferences.fontSize,lineHeight:preferences.fontSize*preferences.lineHeight}]}>{v.text_uthmani}</Text>{preferences.showTranslation&&<Text style={s.ayahTranslation}>{v.translation}</Text>}</View>)}</ScrollView></Page>}

function QuranPreloadScreen({navigation}:any){const{preferences}=useQuranPreferences();const[cached,setCached]=useState(0);const[current,setCurrent]=useState(0);const[running,setRunning]=useState(false);const[usage,setUsage]=useState<any>(null);const[error,setError]=useState('');const runRef=useRef(false);const refresh=()=>{getCacheUsage().then(setUsage);return loadSurahCacheIndex().then(index=>setCached(index.filter(key=>key.endsWith(`:${preferences.scriptEdition}:${preferences.translationEdition}`)).length))};useEffect(()=>{refresh();return()=>{runRef.current=false}},[preferences.scriptEdition,preferences.translationEdition]);const start=async()=>{runRef.current=true;setRunning(true);setError('');const index=await loadSurahCacheIndex();try{for(let id=1;id<=114&&runRef.current;id++){const key=`${id}:${preferences.scriptEdition}:${preferences.translationEdition}`;if(index.includes(key))continue;setCurrent(id);const verses=await getVerses(id,{script:preferences.scriptEdition,translation:preferences.translationEdition});await saveSurahCache(key,verses);setCached(value=>value+1);getCacheUsage().then(setUsage)}}catch(e:any){setError(e.message)}finally{setRunning(false);setCurrent(0)}};return <Page><ToolBar title="Offline Quran" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Offline Quran" size={76}/><Text style={s.dataTitle}>Prepare for offline reading</Text><Text style={s.intro}>Downloads the selected Arabic script and translation from Al Quran Cloud, one Surah at a time. Existing cached Surahs are skipped.</Text><View style={s.preloadScore}><Text style={s.planDays}>{cached}</Text><Text style={s.settingName}>of 114 Surahs cached</Text><View style={s.preloadTrack}><View style={[s.preloadFill,{width:`${cached/114*100}%`} as any]}/></View><Text style={s.meta}>{preferences.scriptName} · {preferences.translationName}{current?` · Downloading Surah ${current}`:''}</Text>{usage&&<Text style={s.cacheUsage}>Quran cache {(usage.byNamespace.quran/1048576).toFixed(1)} MB · limit {(usage.limits.quran/1000000).toFixed(0)} MB · total limit {(usage.limits.total/1000000).toFixed(0)} MB</Text>}</View>{error&&<ErrorState message={error}/>}<View style={s.actionRow}>{!running?<Pressable onPress={start} style={s.primary}><Text style={s.primaryText}>{cached?'Resume preparation':'Preload all'}</Text></Pressable>:<Pressable onPress={()=>{runRef.current=false;setRunning(false)}} style={s.secondary}><Text style={s.secondaryText}>Pause</Text></Pressable>}<Pressable onPress={async()=>{runRef.current=false;await clearSurahCache();setCached(0);getCacheUsage().then(setUsage)}} style={s.dangerButton}><Text style={s.dangerText}>Clear Quran cache</Text></Pressable></View><View style={s.sourceCard}>{ico('shield-checkmark-outline',21,C.green)}<View style={{flex:1}}><Text style={s.sourceTitle}>Cache-first reading</Text><Text style={s.sourceBody}>The reader opens saved text immediately, then checks for live updates when online.</Text></View></View></ScrollView></Page>}

function ReadingPlansScreen({navigation}:any){const[plan,setPlan]=useState<any>(null);useEffect(()=>{loadPlan().then(setPlan)},[]);const start=async(days:number)=>{const next={days,startedAt:Date.now(),completed:[]};await savePlan(next);setPlan(next)};const today=plan?Math.min(plan.days,Math.floor((Date.now()-plan.startedAt)/86400000)+1):0;const toggle=async()=>{const completed=plan.completed.includes(today)?plan.completed.filter((x:number)=>x!==today):[...plan.completed,today];const next={...plan,completed};await savePlan(next);setPlan(next)};return <Page><ToolBar title="Reading plans" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Reading Plans" size={72}/><Text style={s.dataTitle}>Complete the Quran</Text>{!plan?<><Text style={s.intro}>Choose a private local plan. Progress stays on this device.</Text><View style={s.planGrid}>{[30,60,90,120].map(days=><Pressable key={days} onPress={()=>start(days)} style={s.planCard}><Text style={s.planDays}>{days}</Text><Text style={s.settingName}>day plan</Text><Text style={s.meta}>{(604/days).toFixed(1)} pages daily</Text></Pressable>)}</View></>:<><View style={s.summaryScore}><View><Text style={s.nextCardLabel}>CURRENT DAY</Text><Text style={s.zakatNo}>{today} / {plan.days}</Text></View><View><Text style={s.nextCardLabel}>COMPLETED</Text><Text style={s.zakatNo}>{plan.completed.length}</Text></View></View><Pressable onPress={toggle} style={s.planToday}><Text style={s.settingName}>Day {today} reading</Text>{ico(plan.completed.includes(today)?'checkmark-circle':'ellipse-outline',28,C.green)}</Pressable><Pressable onPress={async()=>{await savePlan(null);setPlan(null)}} style={s.dangerButton}><Text style={s.dangerText}>End current plan</Text></Pressable></>}</ScrollView></Page>}
function HifzScreen({navigation}:any){const[chapters,setChapters]=useState<Chapter[]>([]);const[status,setStatus]=useState<Record<number,HifzStatus>>({});const[filter,setFilter]=useState<'all'|HifzStatus>('all');useEffect(()=>{getChapters().then(setChapters);loadHifz().then(setStatus)},[]);const cycle=async(id:number)=>{const current=status[id]||'not-started';const next:HifzStatus=current==='not-started'?'revising':current==='revising'?'memorized':'not-started';const value={...status,[id]:next};setStatus(value);await saveHifz(value)};const shown=chapters.filter(c=>filter==='all'||(status[c.id]||'not-started')===filter);const memorized=Object.values(status).filter(x=>x==='memorized').length;return <Page><ToolBar title="Hifz tracker" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Hifz" size={72}/><Text style={s.dataTitle}>{memorized} of 114 memorized</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{gap:7}}>{(['all','not-started','revising','memorized'] as const).map(value=><ChoicePill key={value} label={value.replace('-',' ')} selected={filter===value} onPress={()=>setFilter(value)}/>)}</ScrollView><View style={{height:13}}/><View style={s.settings}>{shown.map(c=><Pressable key={c.id} onPress={()=>cycle(c.id)} style={s.translationRow}><View style={s.surahNum}><Text style={s.surahNumText}>{c.id}</Text></View><View style={{flex:1}}><Text style={s.settingName}>{c.name_simple}</Text><Text style={s.meta}>{c.verses_count} verses</Text></View><Text style={s.hifzStatus}>{(status[c.id]||'not-started').replace('-',' ')}</Text></Pressable>)}</View></ScrollView></Page>}

function QuranStack(){return <Stack.Navigator screenOptions={{headerShown:false}}><Stack.Screen name="QuranHome" component={QuranHome}/><Stack.Screen name="Reader" component={ReaderScreen}/><Stack.Screen name="Translations" component={TranslationScreen}/><Stack.Screen name="Quran Search" component={QuranSearchScreen}/><Stack.Screen name="Bookmarks" component={BookmarkScreen}/><Stack.Screen name="Notes" component={NotesScreen}/><Stack.Screen name="Note Editor" component={NoteEditor}/><Stack.Screen name="Reader Settings" component={ReaderSettingsScreen}/><Stack.Screen name="Ayah Actions" component={AyahActionsScreen}/><Stack.Screen name="Tafsir Compare" component={TafsirCompareScreen}/><Stack.Screen name="Juz Directory" component={JuzDirectoryScreen}/><Stack.Screen name="Juz Reader" component={JuzReaderScreen}/><Stack.Screen name="Reading Plans" component={ReadingPlansScreen}/><Stack.Screen name="Quran Preload" component={QuranPreloadScreen}/><Stack.Screen name="Hifz" component={HifzScreen}/></Stack.Navigator>}

const libraryGroups=[
  {label:'REMEMBER',title:'Daily remembrance',items:[['hand-left-outline','Duas','Hisn al-Muslim by occasion'],['radio-outline','Tasbih','A quiet, tactile dhikr counter'],['sparkles-outline','99 Names','Learn and reflect on the Beautiful Names']]},
  {label:'LEARN',title:'Knowledge with sources',items:[['chatbubble-ellipses-outline','Hadith','Daily teaching with collection reference']]},
  {label:'PLAN & NEARBY',title:'Practical tools',items:[['calculator-outline','Zakat','Estimate eligible wealth with clarity'],['business-outline','Mosques','Search the live public directory']]},
];
function ExploreHome({navigation}:any){const {width}=useWindowDimensions();const wide=width>=850;let index=0;return <Page><ScrollView contentContainerStyle={s.scroll} showsVerticalScrollIndicator={false}><TopBar overline="PRIVATE · SOURCED · FREE" title="Library" right={<MotionGlyph name="sparkles-outline" size={20}/>}/><Text style={s.intro}>Remembrance, trusted learning and practical tools—organized by purpose rather than hidden in a feature grid.</Text>{libraryGroups.map(group=><View key={group.label}><Text style={s.libraryKicker}>{group.label}</Text><Text style={s.libraryHeading}>{group.title}</Text><View style={s.exploreGrid}>{group.items.map(([iconName,title,desc]:any)=>{const delay=index++*40;return <MotionPress key={title} onPress={()=>navigation.navigate(title)} style={[s.exploreCard,wide&&s.exploreCardWide]}><View style={s.exploreCardInner}><ToolGraphic tool={title} size={64}/><Text style={s.exploreTitle}>{title}</Text><Text style={s.exploreBody}>{desc}</Text><View style={s.exploreArrow}>{ico('arrow-forward',15,C.green)}</View></View></MotionPress>})}</View></View>)}<View style={s.apiPanel}><LiveBadge source="VERIFIED SOURCES"/><Text style={s.apiTitle}>Every text should show where it came from.</Text><Text style={s.apiText}>islamic.app · Al Quran Cloud · AlAdhan</Text></View></ScrollView></Page>}
function ToolBar({title,navigation}:any){const{rtl}=useLanguage();return <View style={s.readerBar}><IconButton name={rtl?'arrow-forward':'arrow-back'} onPress={()=>navigation.goBack()}/><Text style={s.readerName}>{title}</Text><View style={{width:44}}/></View>}
function QiblaScreen({navigation}:any){const{location}=useAppLocation();const[direction,setDirection]=useState<number|null>(null);const[error,setError]=useState('');const load=async()=>{if(!location)return;setDirection(null);setError('');try{setDirection(await getQibla(location.latitude,location.longitude))}catch(e:any){setError(e.message)}};useEffect(()=>{load()},[location?.latitude,location?.longitude]);return <Page><ToolBar title="Qibla direction" navigation={navigation}/>{!location?<View style={s.dataPage}><LocationPrompt compact/></View>:<View style={s.toolPage}><LiveBadge source="ISLAMIC.APP"/><Text style={s.toolEyebrow}>{location.label}</Text>{error?<ErrorState message={error} retry={load}/>:direction===null?<Spinner/>:<><View style={s.compass}><Text style={s.north}>N</Text><View style={[s.compassArrow,{transform:[{rotate:`${direction}deg`}]}]}>{ico('navigate',74,C.green)}</View><View style={s.kaaba}><View style={s.kaabaGold}/></View></View><Text style={s.direction}>{direction.toFixed(1)}°</Text><Text style={s.directionText}>clockwise from true north</Text><Pressable onPress={load} style={s.primary}><Text style={s.primaryText}>Refresh direction</Text></Pressable></>}</View>}</Page>}
function TasbihScreen({navigation}:any){const[count,setCount]=useState(0);const tap=()=>{setCount(x=>x+1);if(Platform.OS!=='web')Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)};return <Page><ToolBar title="Tasbih" navigation={navigation}/><View style={s.toolPage}><Text style={s.toolEyebrow}>CURRENT DHIKR</Text><Text style={s.tasbihAr}>سُبْحَانَ ٱللَّٰهِ</Text><Text style={s.directionText}>Glory be to Allah</Text><Pressable onPress={tap} style={({pressed})=>[s.counter,pressed&&s.counterPress]}><Text style={s.counterNo}>{count}</Text><Text style={s.counterGoal}>GOAL · 33</Text></Pressable><View style={s.row}><Pressable onPress={()=>setCount(0)} style={s.secondary}>{ico('refresh-outline',19,C.green)}<Text style={s.secondaryText}>Reset</Text></Pressable><Pressable onPress={()=>setCount(33)} style={s.secondary}>{ico('flag-outline',19,C.green)}<Text style={s.secondaryText}>Complete</Text></Pressable></View></View></Page>}
function AdhkarScreen({route,navigation}:any){const[category,setCategory]=useState(route.params?.initial||'morning');const[items,setItems]=useState<any[]>([]);const[error,setError]=useState('');const[loading,setLoading]=useState(true);const load=()=>{setLoading(true);setError('');getDuas(category).then(setItems).catch(e=>setError(e.message)).finally(()=>setLoading(false))};useEffect(load,[category]);return <Page><ToolBar title="Daily Adhkar" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool={category==='morning'?'Morning Adhkar':'Evening Adhkar'} size={76}/><Text style={s.dataTitle}>{category==='morning'?'Morning remembrance':'Evening remembrance'}</Text><View style={s.choiceRow}><ChoicePill label="Morning" selected={category==='morning'} onPress={()=>setCategory('morning')}/><ChoicePill label="Evening" selected={category==='evening'} onPress={()=>setCategory('evening')}/></View><View style={{height:16}}/>{error?<ErrorState message={error} retry={load}/>:loading?<Spinner/>:items.map((item:any,i)=><View key={item.number||i} style={s.dataCard}><Text style={s.dataArabic}>{item.arabic}</Text><Text style={s.dataBody}>{item.translation}</Text><Text style={s.dataMeta}>{item.category}</Text></View>)}</ScrollView></Page>}
function DataTool({route,navigation}:any){
 const {location}=useAppLocation(); const title=route.name; const[items,setItems]=useState<any[]>([]); const[error,setError]=useState(''); const[loaded,setLoaded]=useState(false);
 const load=async()=>{setError('');setLoaded(false);try{if(title==='Duas')setItems(await getDuas('morning'));else if(title==='99 Names')setItems(await getNames());else if(title==='Hadith')setItems([await getDailyHadith()]);else if(title==='Mosques'){if(!location){setItems([]);return}setItems(await getNearbyMosques(location.latitude,location.longitude));}}catch(e:any){setError(e.message)}finally{setLoaded(true)}};
 useEffect(()=>{load()},[title,location?.latitude,location?.longitude]);
 return <Page><ToolBar title={title} navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><LiveBadge source="ISLAMIC.APP"/><Text style={s.dataTitle}>{title==='Duas'?'Morning remembrance':title==='99 Names'?'The Beautiful Names':title==='Hadith'?'Hadith of the day':'Mosques near you'}</Text>{title==='Mosques'&&!location?<LocationPrompt compact/>:error?<ErrorState message={error} retry={load}/>:!loaded?<Spinner/>:!items.length?<View style={s.empty}><View style={s.errorIcon}>{ico('location-outline',24,C.green)}</View><Text style={s.errorTitle}>No live records nearby</Text><Text style={s.errorText}>The islamic.app directory does not currently list a public mosque within 50 km of this location.</Text></View>:items.map((item:any,i)=><View key={item.number||item.slug||i} style={s.dataCard}>{title==='99 Names'?<><Text style={s.dataArabic}>{item.name}</Text><Text style={s.dataName}>{item.transliteration}</Text><Text style={s.dataBody}>{item.meaning}</Text></>:title==='Hadith'?<><Text style={s.dataBody}>{item.text}</Text><Text style={s.dataMeta}>{item.collection?.toUpperCase()} · {item.number}</Text></>:title==='Mosques'?<><Text style={s.dataName}>{item.name}</Text><Text style={s.dataBody}>{item.city}, {item.country}</Text><Text style={s.dataMeta}>{item.distance_km?.toFixed?.(1)} km · {item.source}</Text></>:<><Text style={s.dataArabic}>{item.arabic}</Text><Text style={s.dataBody}>{item.translation}</Text><Text style={s.dataMeta}>{item.category}</Text></>}</View>)}</ScrollView></Page>
}
function WeeklySummaryScreen({navigation}:any){const[history,setHistory]=useState<Record<string,string[]>>({});useEffect(()=>{loadPrayerHistory().then(setHistory)},[]);const days=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-(6-i));const key=date.toISOString().slice(0,10);return{date,key,count:(history[key]||[]).length}});const total=days.reduce((sum,d)=>sum+d.count,0);let streak=0;for(let i=0;i<60;i++){const d=new Date();d.setDate(d.getDate()-i);if((history[d.toISOString().slice(0,10)]||[]).length>=5)streak++;else break}return <Page><ToolBar title="Weekly summary" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Weekly Summary" size={78}/><Text style={s.dataTitle}>Your private worship record</Text><Text style={s.intro}>Completion marks are a personal aid, not a judgment of worship. Everything shown here stays on this device.</Text><View style={s.summaryScore}><View><Text style={s.nextCardLabel}>LAST 7 DAYS</Text><Text style={s.zakatNo}>{total} / 35</Text></View><View><Text style={s.nextCardLabel}>CURRENT STREAK</Text><Text style={s.zakatNo}>{streak} days</Text></View></View><Section title="Daily completion"/><View style={s.settings}>{days.map(day=><View key={day.key} style={s.summaryDay}><View style={{flex:1}}><Text style={s.settingName}>{day.date.toLocaleDateString(undefined,{weekday:'long'})}</Text><Text style={s.meta}>{day.date.toLocaleDateString(undefined,{day:'numeric',month:'short'})}</Text></View><View style={s.summaryDots}>{Array.from({length:5}).map((_,i)=><View key={i} style={[s.summaryDot,i<day.count&&s.summaryDotDone]}/>)}</View><Text style={s.progressCount}>{day.count}/5</Text></View>)}</View></ScrollView></Page>}

const CITY_PRESETS=[
 {label:'Dubai, United Arab Emirates',latitude:25.2048,longitude:55.2708},{label:'Makkah, Saudi Arabia',latitude:21.3891,longitude:39.8579},{label:'Madinah, Saudi Arabia',latitude:24.5247,longitude:39.5692},{label:'London, United Kingdom',latitude:51.5074,longitude:-.1278},{label:'New York, United States',latitude:40.7128,longitude:-74.006},{label:'Karachi, Pakistan',latitude:24.8607,longitude:67.0011}
];
function LocationSetupScreen({navigation}:any){const loc=useAppLocation();const[label,setLabel]=useState('');const[lat,setLat]=useState('');const[lng,setLng]=useState('');const save=()=>{const latitude=Number(lat),longitude=Number(lng);if(!label.trim()||!Number.isFinite(latitude)||!Number.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180){Alert.alert('Check location','Enter a label and valid latitude/longitude values.');return}loc.setManual({label:label.trim(),latitude,longitude});navigation.navigate('PrayerHome')};return <Page><ToolBar title="Location setup" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Location" size={76}/><Text style={s.dataTitle}>Choose explicitly</Text><Text style={s.intro}>Prayer, Qibla, Ramadan, and mosque tools share this saved location. It stays on this device.</Text><Pressable onPress={loc.useDevice} style={s.primary}><Text style={s.primaryText}>{loc.locating?'Locating…':'Use current GPS location'}</Text></Pressable><Section title="City shortcuts"/><View style={s.cityGrid}>{CITY_PRESETS.map(city=><Pressable key={city.label} onPress={()=>{loc.setManual(city);navigation.navigate('PrayerHome')}} style={[s.cityCard,loc.location?.label===city.label&&s.cityCardActive]}><Text style={s.cityName}>{city.label}</Text><Text style={s.meta}>{city.latitude.toFixed(3)}, {city.longitude.toFixed(3)}</Text></Pressable>)}</View><Section title="Manual coordinates"/><View style={s.formCard}><Text style={s.inputLabel}>LOCATION LABEL</Text><TextInput value={label} onChangeText={setLabel} placeholder="e.g. Home, Abu Dhabi" style={s.textField}/><View style={s.fieldRow}><View style={{flex:1}}><Text style={s.inputLabel}>LATITUDE</Text><TextInput value={lat} onChangeText={setLat} keyboardType="numbers-and-punctuation" placeholder="24.4539" style={s.textField}/></View><View style={{flex:1}}><Text style={s.inputLabel}>LONGITUDE</Text><TextInput value={lng} onChangeText={setLng} keyboardType="numbers-and-punctuation" placeholder="54.3773" style={s.textField}/></View></View><Pressable onPress={save} style={s.primary}><Text style={s.primaryText}>Save manual location</Text></Pressable></View>{loc.location&&<Pressable onPress={loc.clear} style={s.dangerButton}><Text style={s.dangerText}>Clear saved location</Text></Pressable>}</ScrollView></Page>}

function NotificationScreen({navigation}:any){const{location}=useAppLocation();const{settings,update}=useWorshipSettings();const[health,setHealth]=useState<NotificationHealth>('undetermined');const[working,setWorking]=useState(false);useEffect(()=>{getNotificationHealth().then(setHealth)},[]);const permission=async()=>setHealth(await requestNotificationPermission());const sync=async()=>{if(!location)return Alert.alert('Location needed','Choose a prayer location before scheduling reminders.');setWorking(true);try{const value=await managedPrayerSnapshot(location,settings);const result=await schedulePrayerNotifications(value.snapshot,settings);Alert.alert(result.unsupported?'Saved for installed app':'Reminders updated',result.unsupported?'Web browsers are not scheduled here. Your choices are saved and will apply in the installed iOS or Android app.':`${result.scheduled} notifications scheduled.`)}catch(e:any){Alert.alert('Could not schedule',e.message)}finally{setWorking(false)}};const togglePrayer=(name:string)=>update({prayerReminders:{...settings.prayerReminders,[name]:!settings.prayerReminders[name]}});return <Page><ToolBar title="Prayer reminders" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Notifications" size={76}/><Text style={s.dataTitle}>Gentle, local reminders</Text><Text style={s.intro}>Permission and scheduling happen on your device. No notification profile is sent to us.</Text><View style={s.healthCard}><View style={[s.healthDot,{backgroundColor:health==='granted'?'#3A8A72':health==='denied'?C.coral:C.gold}]}/><View style={{flex:1}}><Text style={s.sourceTitle}>Permission: {health}</Text><Text style={s.sourceBody}>{health==='unsupported'?'System scheduling is available in the installed mobile app.':'You remain in control through system settings.'}</Text></View>{health!=='granted'&&health!=='unsupported'&&<Pressable onPress={permission} style={s.ghostSmall}><Text style={s.ghostText}>Allow</Text></Pressable>}</View><View style={s.settings}><View style={s.setting}><MotionGlyph name="notifications-outline" size={19}/><View style={{flex:1}}><Text style={s.settingName}>Prayer reminders</Text><Text style={s.meta}>Master schedule switch</Text></View><View style={{direction:'ltr'} as any}><Switch value={settings.remindersEnabled} onValueChange={v=>update({remindersEnabled:v})} trackColor={{true:C.green}}/></View></View></View><Text style={s.preferenceLabel}>REMIND ME BEFORE PRAYER</Text><View style={s.choiceRow}>{[0,5,10,15,30].map(value=><ChoicePill key={value} label={value?`${value} min`:'At time'} selected={settings.reminderOffset===value} onPress={()=>update({reminderOffset:value})}/>)}</View><Section title="Per-prayer reminders"/><View style={s.settings}>{['Fajr','Dhuhr','Asr','Maghrib','Isha'].map(name=><View key={name} style={s.setting}><ToolGraphic tool="Notifications" size={42}/><Text style={[s.settingName,{flex:1}]}>{name}</Text><View style={{direction:'ltr'} as any}><Switch value={settings.prayerReminders[name]} onValueChange={()=>togglePrayer(name)} trackColor={{true:C.green}}/></View></View>)}</View><Section title="Quran reminder"/><View style={s.settings}><View style={s.setting}><ToolGraphic tool="Quran" size={42}/><View style={{flex:1}}><Text style={s.settingName}>Daily reading reminder</Text><Text style={s.meta}>{settings.quranReminderTime}</Text></View><View style={{direction:'ltr'} as any}><Switch value={settings.quranReminderEnabled} onValueChange={v=>update({quranReminderEnabled:v})} trackColor={{true:C.green}}/></View></View></View><Text style={s.preferenceLabel}>READING REMINDER TIME</Text><View style={s.choiceRow}>{['06:30','12:30','20:00','22:00'].map(time=><ChoicePill key={time} label={time} selected={settings.quranReminderTime===time} onPress={()=>update({quranReminderTime:time})}/>)}</View><View style={s.actionRow}><Pressable onPress={sync} style={s.primary}><Text style={s.primaryText}>{working?'Scheduling…':'Save & reschedule'}</Text></Pressable><Pressable onPress={()=>sendTestNotification().catch(e=>Alert.alert('Test unavailable',e.message))} style={s.secondary}><Text style={s.secondaryText}>Test notification</Text></Pressable></View></ScrollView></Page>}

const ADHAN_TRACKS=[
 {id:'Makkah',title:'Beautiful Adhan',detail:'Bundled offline · Public domain',source:require('./assets/audio/adhan-doha-public-domain.mp3')},
 {id:'Doha Fajr',title:'Doha Fajr Adhan',detail:'Public domain · Internet Archive',source:'https://archive.org/download/adhan.recordings.from.doha.qatar/Adhan_Doha_Qatar_01_Fajr_Adhan.mp3'},
 {id:'Doha Classic',title:'Doha Dhuhr Adhan',detail:'Public domain · Internet Archive',source:'https://archive.org/download/adhan.recordings.from.doha.qatar/Adhan_Doha_Qatar_02_Dhuhr_Adhan.mp3'}
];
function AdhanScreen({navigation}:any){const{settings,update}=useWorshipSettings();const selected=ADHAN_TRACKS.find(x=>x.id===settings.adhanReciter)||ADHAN_TRACKS[0];const player=useAudioPlayer(selected.source);const status=useAudioPlayerStatus(player);const toggle=()=>status.playing?player.pause():player.play();useEffect(()=>()=>{player.pause()},[player]);return <Page><ToolBar title="Adhan" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Adhan" size={82}/><Text style={s.dataTitle}>Choose an Adhan</Text><Text style={s.intro}>Preview a recording and choose which prayers may use Adhan. The bundled selection works without a network connection.</Text><View style={s.audioPreview}><Pressable accessibilityLabel={status.playing?'Pause Adhan preview':'Play Adhan preview'} onPress={toggle} style={s.audioPlay}>{ico(status.playing?'pause':'play',25,C.white)}</Pressable><View style={{flex:1}}><Text style={s.profileName}>{selected.title}</Text><Text style={s.profileSub}>{selected.detail}</Text></View><Pressable onPress={()=>{player.seekTo(0);player.pause()}}>{ico('stop-circle-outline',26,C.white)}</Pressable></View><Section title="Recordings"/><View style={s.settings}>{ADHAN_TRACKS.map(track=><Pressable accessibilityRole="radio" accessibilityState={{selected:track.id===selected.id}} key={track.id} onPress={()=>update({adhanReciter:track.id})} style={s.setting}><ToolGraphic tool="Adhan" size={44}/><View style={{flex:1}}><Text style={s.settingName}>{track.title}</Text><Text style={s.meta}>{track.detail}</Text></View>{ico(track.id===selected.id?'checkmark-circle':'ellipse-outline',20,track.id===selected.id?C.green:C.muted)}</Pressable>)}</View><Section title="Use Adhan for"/><View style={s.settings}>{['Fajr','Dhuhr','Asr','Maghrib','Isha'].map(name=><View key={name} style={s.setting}><Text style={[s.settingName,{flex:1}]}>{name}</Text><View style={{direction:'ltr'} as any}><Switch value={settings.adhanEnabled[name]} onValueChange={v=>update({adhanEnabled:{...settings.adhanEnabled,[name]:v}})} trackColor={{true:C.green}}/></View></View>)}</View><View style={s.sourceCard}>{ico('information-circle-outline',21,C.green)}<View style={{flex:1}}><Text style={s.sourceTitle}>Audio rights</Text><Text style={s.sourceBody}>Bundled and streamed Doha recordings: Internet Archive Public Domain Mark 1.0.</Text></View></View></ScrollView></Page>}

function GuideDirectory({navigation}:any){return <Page><ToolBar title="Worship guides" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool="Worship guides" size={78}/><Text style={s.dataTitle}>Learn with references</Text><Text style={s.intro}>Concise educational overviews with transparent Qur’an and Hadith references. Detailed rulings should be learned from a qualified local scholar.</Text><View style={s.guideGrid}>{WORSHIP_GUIDES.map(guide=><MotionPress key={guide.id} onPress={()=>navigation.navigate('Guide Detail',{guide})} style={s.guideCard}><View style={s.guideCardInner}><ToolGraphic tool={guide.id} size={62}/><Text style={s.exploreTitle}>{guide.title}</Text><Text style={s.exploreBody}>{guide.subtitle}</Text><View style={s.exploreArrow}>{ico('arrow-forward',15,C.green)}</View></View></MotionPress>)}</View></ScrollView></Page>}
function GuideDetail({route,navigation}:any){const guide:WorshipGuide=route.params.guide;return <Page><ToolBar title={guide.title} navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><ToolGraphic tool={guide.id} size={82}/><Text style={s.dataTitle}>{guide.subtitle}</Text>{guide.arabic&&<Text style={s.guideArabic}>{guide.arabic}</Text>}<Text style={s.intro}>{guide.introduction}</Text><Section title="Step by step"/><View style={s.settings}>{guide.steps.map((step,i)=><View key={step} style={s.guideStep}><View style={s.stepNo}><Text style={s.stepNoText}>{i+1}</Text></View><Text style={s.guideStepText}>{step}</Text></View>)}</View>{guide.note&&<View style={s.guideNote}><Text style={s.sourceTitle}>Important note</Text><Text style={s.sourceBody}>{guide.note}</Text></View>}<Section title="References"/>{guide.references.map(ref=><Pressable key={ref.url} onPress={()=>Linking.openURL(ref.url)} style={s.referenceRow}><Text style={s.settingName}>{ref.label}</Text>{ico('open-outline',18,C.green)}</Pressable>)}</ScrollView></Page>}

function HijriCalendarScreen({navigation}:any){const{location}=useAppLocation();const[days,setDays]=useState<CalendarDay[]>([]);const[error,setError]=useState('');const now=new Date();const load=async()=>{if(!location)return;setError('');setDays([]);try{setDays(await getGregorianCalendar(location.latitude,location.longitude,now.getMonth()+1,now.getFullYear()))}catch(e:any){setError(e.message)}};useEffect(()=>{load()},[location?.latitude,location?.longitude]);const first=days[0]?.gregorian.split('-').map(Number);const offset=first?new Date(first[2],first[1]-1,first[0]).getDay():0;return <Page><ToolBar title="Hijri calendar" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}>{!location?<LocationPrompt compact/>:<><View style={s.calendarIntro}><LiveBadge source="ALADHAN"/><Text style={s.calendarMonth}>{now.toLocaleDateString('en',{month:'long',year:'numeric'})}</Text><Text style={s.calendarHijri}>{days.length?`${days[0].hijriMonth} – ${days[days.length-1].hijriMonth} ${days[0].hijriYear} AH`:''}</Text></View>{error?<ErrorState message={error} retry={load}/>:!days.length?<Spinner/>:<><View style={s.weekHead}>{['S','M','T','W','T','F','S'].map((d,i)=><Text key={i} style={s.weekLabel}>{d}</Text>)}</View><View style={s.calendarGrid}>{Array.from({length:offset}).map((_,i)=><View key={`e${i}`} style={s.calendarCell}/>) }{days.map((d,i)=><View key={d.gregorian} style={[s.calendarCell,d.gregorian.startsWith(String(now.getDate()).padStart(2,'0'))&&s.calendarToday]}><Text style={s.gregorianDay}>{i+1}</Text><Text style={s.hijriDay}>{d.hijriDay}</Text></View>)}</View><View style={s.calendarLegend}><View style={s.legendDot}/><Text style={s.sourceBody}>Large number: Gregorian · Small number: Hijri</Text></View></>}</>}</ScrollView></Page>}
function RamadanScreen({navigation}:any){const{location}=useAppLocation();const[days,setDays]=useState<CalendarDay[]>([]);const[year,setYear]=useState<number|null>(null);const[error,setError]=useState('');const load=async()=>{if(!location)return;setError('');setDays([]);try{const snap=await getPrayerSnapshot(location.latitude,location.longitude);const target=snap.hijriMonth>9?snap.hijriYear+1:snap.hijriYear;setYear(target);setDays(await getRamadanCalendar(location.latitude,location.longitude,target));}catch(e:any){setError(e.message)}};useEffect(()=>{load()},[location?.latitude,location?.longitude]);return <Page><ToolBar title="Ramadan" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}>{!location?<LocationPrompt compact/>:<><LinearGradient colors={['#2A2849','#5146A4']} style={s.ramadanHero}><LiveBadge source="ALADHAN"/><Text style={s.ramadanArabic}>رَمَضَان</Text><Text style={s.ramadanTitle}>Ramadan {year||''} AH</Text><Text style={s.ramadanSub}>A live 30-day Suhoor and Iftar timetable for {location.label}.</Text></LinearGradient>{error?<ErrorState message={error} retry={load}/>:!days.length?<Spinner/>:<><Section title="Fasting timetable" action={`${days.length} days`}/><View style={s.ramadanList}>{days.map(d=>{const fajr=d.prayers.find(p=>p.name==='Fajr');const maghrib=d.prayers.find(p=>p.name==='Maghrib');return <View key={d.gregorian} style={s.ramadanRow}><View style={s.ramadanDay}><Text style={s.ramadanDayNo}>{d.hijriDay}</Text><Text style={s.ramadanDayLabel}>RAM</Text></View><View style={{flex:1}}><Text style={s.ramadanDate}>{d.weekday} · {d.gregorian}</Text><Text style={s.meta}>{location.label}</Text></View><View style={s.fastTime}><Text style={s.fastLabel}>SUHOOR</Text><Text style={s.fastValue}>{fajr?.time}</Text></View><View style={s.fastTime}><Text style={s.fastLabel}>IFTAR</Text><Text style={s.fastValue}>{maghrib?.time}</Text></View></View>})}</View></>}</>}</ScrollView></Page>}
function ZakatScreen({navigation}:any){const[value,setValue]=useState('');const total=Number(value.replace(/,/g,''))||0;return <Page><ToolBar title="Zakat calculator" navigation={navigation}/><View style={s.dataPage}><Text style={s.dataTitle}>Calculate with clarity</Text><Text style={s.intro}>Enter your eligible wealth after deductible liabilities. Confirm the nisab threshold with a qualified local scholar.</Text><Text style={s.inputLabel}>ZAKATABLE WEALTH</Text><TextInput keyboardType="numeric" value={value} onChangeText={setValue} placeholder="0.00" style={s.moneyInput}/><LinearGradient colors={['#2A2849','#5146A4']} style={s.zakatResult}><Text style={s.nextCardLabel}>ESTIMATED ZAKAT · 2.5%</Text><Text style={s.zakatNo}>{(total*.025).toLocaleString(undefined,{maximumFractionDigits:2})}</Text></LinearGradient></View></Page>}
function ExploreStack(){return <Stack.Navigator screenOptions={{headerShown:false}}><Stack.Screen name="ExploreHome" component={ExploreHome}/><Stack.Screen name="Qibla" component={QiblaScreen}/><Stack.Screen name="Tasbih" component={TasbihScreen}/><Stack.Screen name="Adhkar" component={AdhkarScreen}/>{['Duas','99 Names','Hadith','Mosques'].map(x=><Stack.Screen key={x} name={x} component={DataTool}/>) }<Stack.Screen name="Zakat" component={ZakatScreen}/></Stack.Navigator>}
function PrayerStack(){return <Stack.Navigator screenOptions={{headerShown:false}}><Stack.Screen name="PrayerHome" component={PrayerScreen}/><Stack.Screen name="Qibla" component={QiblaScreen}/><Stack.Screen name="Location Setup" component={LocationSetupScreen}/><Stack.Screen name="Weekly Summary" component={WeeklySummaryScreen}/><Stack.Screen name="Notifications" component={NotificationScreen}/><Stack.Screen name="Adhan" component={AdhanScreen}/><Stack.Screen name="Worship Guides" component={GuideDirectory}/><Stack.Screen name="Guide Detail" component={GuideDetail}/><Stack.Screen name="Hijri Calendar" component={HijriCalendarScreen}/><Stack.Screen name="Ramadan" component={RamadanScreen}/><Stack.Screen name="Mosques" component={DataTool}/></Stack.Navigator>}
const PRAYER_METHODS=[{id:8,name:'Gulf Region'},{id:4,name:'Umm al-Qura'},{id:3,name:'Muslim World League'},{id:5,name:'Egyptian Authority'},{id:1,name:'Karachi'},{id:2,name:'North America'}];
function ChoicePill({label,selected,onPress}:{label:string;selected:boolean;onPress:()=>void}){return <Pressable accessibilityRole="radio" accessibilityState={{selected}} onPress={onPress} style={[s.choicePill,selected&&s.choicePillActive]}><Text style={[s.choiceText,selected&&s.choiceTextActive]}>{label}</Text></Pressable>}
function SettingsScreen(){const{language,rtl,setLanguage}=useLanguage();const{settings,update}=useWorshipSettings();return <Page><ScrollView contentContainerStyle={s.scroll}><TopBar overline={rtl?'خصوصية بلا حساب':'PRIVATE BY DESIGN'} title={rtl?'الإعدادات':'Settings'} right={<MotionGlyph name="shield-checkmark-outline" size={20}/>}/><LinearGradient colors={['#2A2849','#5146A4']} style={s.privacyHero}><MotionGlyph name="shield-checkmark-outline" size={25} inverse/><View style={{flex:1}}><Text style={s.profileName}>{rtl?'لا حساب. لا تتبع.':'No account. No tracking.'}</Text><Text style={s.profileSub}>{rtl?'تبقى عبادتك خاصة وتظل تفضيلاتك على هذا الجهاز.':'Your worship stays private and your preferences remain on this device.'}</Text></View></LinearGradient><View style={s.privacyPoints}><View style={s.privacyPoint}>{ico('person-remove-outline',19,C.green)}<Text style={s.privacyPointText}>{rtl?'دون تسجيل':'No sign-up'}</Text></View><View style={s.privacyPoint}>{ico('cloud-offline-outline',19,C.green)}<Text style={s.privacyPointText}>{rtl?'دون ملف سحابي':'No cloud profile'}</Text></View><View style={s.privacyPoint}>{ico('analytics-outline',19,C.green)}<Text style={s.privacyPointText}>{rtl?'دون تتبع إعلاني':'No ad tracking'}</Text></View></View>
<Section title={rtl?'حساب أوقات الصلاة':'Prayer calculation'}/><View style={s.preferencePanel}><View style={s.preferenceHead}><ToolGraphic tool="Qibla" size={54}/><View style={{flex:1}}><Text style={s.settingName}>{rtl?'طريقة الحساب':'Calculation method'}</Text><Text style={s.meta}>{rtl?'تُحفظ على هذا الجهاز وتُطبق على جميع مواقيت الصلاة.':'Saved on this device and applied throughout the app.'}</Text></View></View><View style={s.choiceGrid}>{PRAYER_METHODS.map(method=><ChoicePill key={method.id} label={method.name} selected={settings.calculationMethod===method.id} onPress={()=>update({calculationMethod:method.id,calculationMethodName:method.name})}/>)}</View><Text style={s.preferenceLabel}>{rtl?'المذهب لحساب العصر':'ASR MADHAB'}</Text><View style={s.choiceRow}><ChoicePill label="Shafi" selected={settings.madhab==='shafi'} onPress={()=>update({madhab:'shafi'})}/><ChoicePill label="Hanafi" selected={settings.madhab==='hanafi'} onPress={()=>update({madhab:'hanafi'})}/></View><Text style={s.preferenceLabel}>{rtl?'تنسيق الوقت':'TIME FORMAT'}</Text><View style={s.choiceRow}><ChoicePill label="12 hour" selected={settings.timeFormat==='12'} onPress={()=>update({timeFormat:'12'})}/><ChoicePill label="24 hour" selected={settings.timeFormat==='24'} onPress={()=>update({timeFormat:'24'})}/></View></View>
<Section title={rtl?'التفضيلات':'Preferences'}/><View style={s.settings}><View style={s.setting}><MotionGlyph name="language-outline" size={19}/><View style={{flex:1}}><Text style={s.settingName}>{rtl?'English interface':'Arabic interface'}</Text><Text style={s.meta}>{rtl?'Left-to-right layout':'واجهة عربية من اليمين إلى اليسار'}</Text></View><View style={{direction:'ltr'} as any}><Switch value={language==='ar'} onValueChange={v=>setLanguage(v?'ar':'en')} trackColor={{true:C.green}}/></View></View><View style={s.setting}><ToolGraphic tool="Arabic Quran" size={44}/><View style={{flex:1}}><Text style={s.settingName}>{rtl?'قراءة القرآن':'Quran reading'}</Text><Text style={s.meta}>{rtl?'النص العثماني · صحيح إنترناشيونال':'Uthmani Arabic · Sahih International English'}</Text></View></View></View><View style={s.sourceCard}>{ico('server-outline',21,C.green)}<View><Text style={s.sourceTitle}>{rtl?'مصادر بيانات مباشرة بلا مفاتيح':'Live, keyless data sources'}</Text><Text style={s.sourceBody}>islamic.app · Al Quran Cloud · AlAdhan</Text></View></View></ScrollView></Page>}
function Tabs(){const{width}=useWindowDimensions();const{rtl}=useLanguage();const web=Platform.OS==='web';const barWidth=Math.min(Math.max(width-24,340),640);const responsiveBar:any=web?{left:'50%' as any,right:undefined,width:barWidth,transform:[{translateX:-barWidth/2}],direction:rtl?'rtl':'ltr'}:{};const labels:any={Today:'اليوم',Prayer:'الصلاة',Quran:'القرآن',Library:'المكتبة',Settings:'الإعدادات'};return <Tab.Navigator screenOptions={({route})=>({headerShown:false,tabBarHideOnKeyboard:true,tabBarActiveTintColor:C.green,tabBarInactiveTintColor:'#8B909D',tabBarLabel:rtl?labels[route.name]:route.name,tabBarStyle:[s.tabbar,responsiveBar],tabBarLabelStyle:s.tabLabel,tabBarIcon:({color,focused})=>ico(({Today:focused?'home':'home-outline',Prayer:focused?'time':'time-outline',Quran:focused?'book':'book-outline',Library:focused?'grid':'grid-outline',Settings:focused?'settings':'settings-outline'}as any)[route.name],21,color)})}><Tab.Screen name="Today" component={HomeScreen}/><Tab.Screen name="Prayer" component={PrayerStack}/><Tab.Screen name="Quran" component={QuranStack}/><Tab.Screen name="Library" component={ExploreStack}/><Tab.Screen name="Settings" component={SettingsScreen}/></Tab.Navigator>}
